import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // No vm.assume needed; let the fuzzer explore the full bytes4 space.
        // The reference C includes supportsInterface via AccessControl, the mutant only delegates to ERC165.
        // We check the general rule: for any interfaceId, if the reference (C) returns true, then the mutant must also return true.
        // Since we cannot run the mutant directly, we encode the expected mutant behavior:
        // The mutant only supports exactly type(IERC165).interfaceId.
        // So the rule becomes: if c.supportsInterface(interfaceId) is true, then interfaceId must equal type(IERC165).interfaceId.
        // This is an invariant the reference satisfies (it returns true for IAccessControl and IERC165, but we check the implication).
        // The bug violates this: when interfaceId == type(IAccessControl).interfaceId, reference returns true, but the implication fails because interfaceId != type(IERC165).interfaceId.
        bool refSupports = c.supportsInterface(interfaceId);
        if (refSupports) {
            assertTrue(interfaceId == type(IERC165).interfaceId);
        }
    }
}

